// Нода "Метрики": считает всё детерминированно, LLM потом только пишет текст.
// Конкурент попадает в сравнение только если снимок получен и на этой, и на прошлой неделе.
const rows = $input.all().map(i => i.json).filter(r => r.competitor && r.week);

const norm = s => String(s ?? '').trim().toLowerCase();
const unk = v => ['', 'unknown'].includes(norm(v));
const r1 = n => (n == null ? null : Math.round(n * 10) / 10);
const med = a => {
  if (!a.length) return null;
  const s = [...a].sort((x, y) => x - y), h = Math.floor(s.length / 2);
  return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2;
};
// максимальный % в тексте скидки; "10% бонусами" и т.п. скидкой не считаем
const parsePct = d => {
  const t = String(d ?? '');
  if (/бонус/i.test(t)) return null;
  const m = t.match(/\d+(?:[.,]\d+)?\s*%/g);
  return m ? Math.max(...m.map(x => parseFloat(x.replace(',', '.')))) : null;
};
const count = (arr, f) => arr.reduce((a, r) => { const k = r[f] || 'unknown'; a[k] = (a[k] || 0) + 1; return a; }, {});
const nurl = u => String(u ?? '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
const isoWeek = (yyyy, mm, dd) => {
  const d = new Date(Date.UTC(yyyy, mm - 1, dd));
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const y = d.getUTCFullYear();
  return `${y}-W${String(Math.ceil(((d - Date.UTC(y, 0, 1)) / 86400000 + 1) / 7)).padStart(2, '0')}`;
};

for (const r of rows) {
  r.brand_n = String(r.brand ?? '').trim().toUpperCase();
  // ключ акции: по нему определяем новые/завершённые между неделями
  r.key = [norm(r.competitor), norm(r.title), r.brand_n].join('|');
  r.pct = parsePct(r.discount);
}

// ---- недели: текущая = неделя запуска, прошлая = последняя более ранняя в базе ----
const cur = $now.toFormat("kkkk-'W'WW");
const weeks = [...new Set(rows.map(r => r.week))].sort();
if (!weeks.includes(cur)) throw new Error(`Нет снимков за неделю ${cur}: ни один сайт не дал данных. Проверьте листы Errors и Websites.`);
const older = weeks.filter(w => w < cur);
if (!older.length) throw new Error('Нужно минимум два снимка (колонка week), найдено: ' + weeks.length);
const prev = older.at(-1);
const W = w => rows.filter(r => r.week === w);
const A_all = W(cur), B_all = W(prev);

// ---- что не удалось собрать на этой неделе (лист Errors) ----
let sites = [], errRows = [];
try { sites = $('Чтение список сайтов / Лист Websites').all().map(i => i.json).filter(r => r.page); } catch (e) { sites = []; }
try { errRows = $('Чтение Errors').all().map(i => i.json).filter(r => r.url && r.checked_at); } catch (e) { errRows = []; }

const siteCompany = {};
for (const s of sites) siteCompany[nurl(s.page)] = String(s.company ?? '').trim();
for (const r of rows) if (!siteCompany[nurl(r.url)]) siteCompany[nurl(r.url)] = r.competitor;

const weekOfTs = ts => { const m = String(ts).match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? isoWeek(+m[1], +m[2], +m[3]) : ''; };
const pagesWithRows = new Set(A_all.map(r => nurl(r.url)));
const failedPages = {};
for (const e of errRows) {
  const k = nurl(e.url);
  if (weekOfTs(e.checked_at) !== cur) continue;
  if (pagesWithRows.has(k)) continue;                    // страницу потом собрали успешно: ошибку игнорируем
  failedPages[k] = {
    url: e.url,
    competitor: siteCompany[k] || k.split('/')[0],
    status: String(e.httpstatus ?? '').trim() || 'ошибка',
    note: String(e.title ?? '').trim().slice(0, 120),
  };
}

const competitors = [...new Set([...rows.map(r => r.competitor), ...Object.values(failedPages).map(p => p.competitor)])];
const STATUS_RU = { no_snapshot: 'снимок не получен', incomplete: 'снимок неполный', no_baseline: 'нет снимка за прошлую неделю' };
const coverageBy = {};
for (const c of competitors) {
  const pages = Object.values(failedPages).filter(p => p.competitor === c);
  const hasCur = A_all.some(r => r.competitor === c), hasPrev = B_all.some(r => r.competitor === c);
  let status = 'ok', reason = '';
  if (!hasCur) { status = 'no_snapshot'; reason = pages.length ? pages.map(p => `${p.status}`).join(', ') : 'нет данных за неделю'; }
  else if (pages.length) { status = 'incomplete'; reason = 'часть страниц не получена: ' + pages.map(p => p.status).join(', '); }
  else if (!hasPrev) { status = 'no_baseline'; reason = `нет данных за ${prev}`; }
  coverageBy[c] = { status, status_ru: STATUS_RU[status] ?? '', reason, pages };
}
const comparable = competitors.filter(c => coverageBy[c].status === 'ok');
const coverage = {
  run_week: cur, compared_with: prev, comparable,
  problems: competitors.filter(c => coverageBy[c].status !== 'ok').map(c => ({ competitor: c, ...coverageBy[c] })),
};

// ---- сравнение: только конкуренты с полным снимком на обеих неделях ----
const A = A_all.filter(r => comparable.includes(r.competitor));
const B = B_all.filter(r => comparable.includes(r.competitor));
const kc = new Set(A.map(r => r.key)), kp = new Set(B.map(r => r.key));
const newPromos = A.filter(r => !kp.has(r.key));
const endedPromos = B.filter(r => !kc.has(r.key));

const byCompetitor = {};
for (const c of competitors) {
  const cov = coverageBy[c];
  const a = A_all.filter(r => r.competitor === c), b = B_all.filter(r => r.competitor === c);
  if (cov.status !== 'ok') {
    byCompetitor[c] = { comparable: false, status: cov.status, status_ru: cov.status_ru, reason: cov.reason, total_cur: a.length, total_prev: b.length };
    continue;
  }
  const pcts = a.map(r => r.pct).filter(x => x != null);
  const known = a.filter(r => !unk(r.price_segment));
  byCompetitor[c] = {
    comparable: true,
    total_cur: a.length, total_prev: b.length,
    new: a.filter(r => !kp.has(r.key)).length,
    ended: b.filter(r => !kc.has(r.key)).length,
    types_cur: count(a, 'promotion_type'), types_prev: count(b, 'promotion_type'),
    mechanics_cur: count(a, 'promotion_mechanic'), mechanics_prev: count(b, 'promotion_mechanic'),
    short_term_cur: a.filter(r => r.duration_type === 'short_term').length,
    short_term_prev: b.filter(r => r.duration_type === 'short_term').length,
    discount_depth: { n: pcts.length, mean: r1(pcts.length ? pcts.reduce((s, x) => s + x, 0) / pcts.length : null), median: med(pcts), max: pcts.length ? Math.max(...pcts) : null },
    segments_known: known.length,
    premium_luxe_share: known.length ? r1(known.filter(r => ['premium', 'luxe'].includes(r.price_segment)).length / known.length * 100) : null,
  };
}

const types = [...new Set(rows.map(r => r.promotion_type || 'unknown'))];
const kpi = {
  total: { cur: A.length, prev: B.length },
  new: newPromos.length, ended: endedPromos.length,
  share_new_pct: A.length ? r1(newPromos.length / A.length * 100) : null,
  short_term: { cur: A.filter(r => r.duration_type === 'short_term').length, prev: B.filter(r => r.duration_type === 'short_term').length },
  types: Object.fromEntries(types.map(t => [t, { cur: A.filter(r => (r.promotion_type || 'unknown') === t).length, prev: B.filter(r => (r.promotion_type || 'unknown') === t).length }])),
};

// бренды, у которых есть акции минимум у двух конкурентов в текущем снимке
const brandMap = {};
for (const r of A_all) {
  if (['MULTIPLE', 'UNKNOWN', ''].includes(r.brand_n)) continue;
  (brandMap[r.brand_n] ??= {})[r.competitor] = [r.promotion_mechanic, r.discount].filter(Boolean).join(' ');
}
const brand_overlap = Object.entries(brandMap).filter(([, v]) => Object.keys(v).length >= 2).map(([brand, by]) => ({ brand, by_competitor: by }));

const slim = r => ({ competitor: r.competitor, title: r.title, brand: r.brand, discount: r.discount || null, mechanic: r.promotion_mechanic, type: r.promotion_type });
const top_discounts = A_all.filter(r => r.pct != null).sort((x, y) => y.pct - x.pct).slice(0, 5).map(slim);

const share = (arr, f) => (arr.length ? r1(arr.filter(r => unk(r[f])).length / arr.length * 100) : 0);
const quality = {
  rows_cur: A_all.length,
  unknown_segment_pct: share(A_all, 'price_segment'),
  unknown_category_pct: share(A_all, 'product_category'),
  unknown_duration_pct: share(A_all, 'duration_type'),
  brand_multiple_or_unknown_pct: r1(A_all.filter(r => ['MULTIPLE', 'UNKNOWN', ''].includes(r.brand_n)).length / A_all.length * 100),
  high_confidence_pct: r1(A_all.filter(r => r.confidence === 'high').length / A_all.length * 100),
  by_competitor_unknown_segment_pct: Object.fromEntries(competitors.filter(c => A_all.some(r => r.competitor === c)).map(c => [c, share(A_all.filter(r => r.competitor === c), 'price_segment')])),
};

return [{
  json: {
    weeks_total: weeks.length, cur_week: cur, prev_week: prev,
    cur_date: A_all[0]?.date ?? null, prev_date: B_all[0]?.date ?? null,
    competitors, coverage, kpi, byCompetitor, brand_overlap, top_discounts,
    new_promos: newPromos.slice(0, 20).map(slim),
    ended_promos: endedPromos.slice(0, 20).map(slim),
    quality,
    notes: [
      'Новая/завершённая акция определяется по связке конкурент+заголовок+бренд.',
      'Глубина скидки: максимальный % из текста; проценты бонусами не учитываются; "до -60%" это потолок, а не фикс.',
      'В сравнение входят только конкуренты с полным снимком на обеих неделях.',
    ],
  },
}];

// Нода "Собрать HTML": подставляет метрики и текст LLM в письмо
const m = $('Метрики').first().json;
let ai = $input.first().json.output ?? $input.first().json;
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = { summary: ai, insights: [] }; } }

// LLM не ответила: отправляем отчёт с расчётными таблицами, без текстовых выводов
if (!ai || typeof ai !== 'object' || !ai.summary) {
  ai = { summary: 'Текстовые выводы недоступны: модель не вернула ответ. Ниже расчётные показатели.', insights: [] };
}

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const delta = (c, p) => { const d = c - p; return d > 0 ? '+' + d : String(d); };
const TYPE_RU = { price: 'Цена', gift: 'Подарок', loyalty: 'Лояльность', bundle: 'Набор', service: 'Сервис', other: 'Прочее', unknown: 'Не определено' };
const td = 'padding:6px 10px;border-bottom:1px solid #e5e5e5;';
const th = 'padding:6px 10px;border-bottom:2px solid #999;text-align:left;font-weight:600;';
const table = (head, body) =>
  `<table style="border-collapse:collapse;font-size:14px;margin:8px 0 16px">` +
  `<tr>${head.map(h => `<th style="${th}">${esc(h)}</th>`).join('')}</tr>` +
  body.map(r => `<tr>${r.map(c => `<td style="${td}">${esc(c)}</td>`).join('')}</tr>`).join('') + `</table>`;
const ul = a => (a && a.length ? `<ul>${a.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '');

// KPI
const kpiRows = [
  ['Акций в снимке', m.kpi.total.prev, m.kpi.total.cur, delta(m.kpi.total.cur, m.kpi.total.prev)],
  ...['price', 'gift', 'loyalty'].filter(t => m.kpi.types[t]).map(t => [TYPE_RU[t], m.kpi.types[t].prev, m.kpi.types[t].cur, delta(m.kpi.types[t].cur, m.kpi.types[t].prev)]),
  ['Краткосрочные', m.kpi.short_term.prev, m.kpi.short_term.cur, delta(m.kpi.short_term.cur, m.kpi.short_term.prev)],
];

// оборот акций
const churnRows = m.competitors.map(c => {
  const x = m.byCompetitor[c];
  if (x.comparable === false) return [c, x.total_prev || '-', x.total_cur || '-', '-', '-', x.status_ru + (x.reason ? ' (' + x.reason + ')' : '')];
  return [c, x.total_prev, x.total_cur, x.new, x.ended, x.total_cur ? Math.round(x.new / x.total_cur * 100) + '%' : '-'];
});
const okCompetitors = m.competitors.filter(c => m.byCompetitor[c].comparable !== false);

// график: структура типов акций по конкурентам (текущая неделя), QuickChart
const mixTypes = ['price', 'gift', 'loyalty'];
const mix = okCompetitors.map(c => {
  const x = m.byCompetitor[c], tot = x.total_cur || 1;
  const row = Object.fromEntries(mixTypes.map(t => [t, Math.round((x.types_cur[t] || 0) / tot * 100)]));
  row.other = Math.max(0, 100 - mixTypes.reduce((s, t) => s + row[t], 0));
  return row;
});
const colors = { price: '#2a78d6', gift: '#c9c8c0', loyalty: '#dfdfd8', other: '#eeeeea' };
const chartCfg = {
  type: 'bar',
  data: {
    labels: okCompetitors,
    datasets: [...mixTypes, 'other'].map(t => ({ label: TYPE_RU[t === 'other' ? 'other' : t], data: mix.map(r => r[t]), backgroundColor: colors[t] })),
  },
  options: {
    indexAxis: 'y',
    plugins: { title: { display: true, text: 'Структура акций по типам, % (неделя ' + m.cur_week + ')' }, legend: { position: 'bottom' } },
    scales: { x: { stacked: true, max: 100 }, y: { stacked: true } },
  },
};
const chartUrl = 'https://quickchart.io/chart?w=700&h=300&bkg=white&c=' + encodeURIComponent(JSON.stringify(chartCfg));

// механики: что изменилось
const mechRows = [];
for (const c of okCompetitors) {
  const x = m.byCompetitor[c];
  const keys = new Set([...Object.keys(x.mechanics_cur), ...Object.keys(x.mechanics_prev)]);
  for (const k of keys) {
    const cu = x.mechanics_cur[k] || 0, pr = x.mechanics_prev[k] || 0;
    if (Math.abs(cu - pr) >= 2) mechRows.push([c, k, pr, cu, delta(cu, pr)]);
  }
}
mechRows.sort((a, b) => Math.abs(b[4]) - Math.abs(a[4]));

// глубина скидок
const depthRows = okCompetitors.map(c => { const d = m.byCompetitor[c].discount_depth; return [c, d.n, d.mean ?? '-', d.median ?? '-', d.max ?? '-']; });

// пересечения брендов
const overlapRows = m.brand_overlap.slice(0, 12).map(o => [o.brand, ...m.competitors.map(c => o.by_competitor[c] || '-')]);

// качество данных
const q = m.quality;
const qualityWarn = q.unknown_segment_pct > 40 || q.unknown_category_pct > 40 || q.unknown_duration_pct > 40;


// предупреждение о неполных данных
const probs = (m.coverage && m.coverage.problems) || [];
const bannerHtml = probs.length ? `<div style="border:1px solid #c33;background:#fff4f4;padding:10px 14px;margin:12px 0;border-radius:4px">
<b>Внимание: данные за неделю неполные.</b>
<ul style="margin:6px 0 0">${probs.map(p => `<li><b>${esc(p.competitor)}</b>: ${esc(p.status_ru)}${p.reason ? ' (' + esc(p.reason) + ')' : ''}${p.pages && p.pages.length ? '. Страницы: ' + p.pages.map(x => esc(x.url) + ' — ' + esc(x.status) + (x.note ? ', ' + esc(x.note) : '')).join('; ') : ''}</li>`).join('')}</ul>
<p style="margin:6px 0 0;color:#555;font-size:13px">Такие конкуренты не участвуют в сравнении: их отсутствие в данных не означает, что акции закончились. В показателях учтены: ${esc((m.coverage.comparable || []).join(', ') || 'никто')}.</p></div>` : '';

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:760px;color:#222;line-height:1.45">
<h1 style="font-size:22px">Competitive Intelligence: промо конкурентов, ${esc(m.cur_week)}</h1>
<p style="color:#666">Неделя ${esc(m.cur_week)} к ${esc(m.prev_week)}. Конкуренты: ${esc(m.competitors.join(', '))}.</p>

${bannerHtml}
<h2 style="font-size:18px">Главное</h2>
<p>${esc(ai.summary)}</p>
${ul(ai.insights)}

<h2 style="font-size:18px">Динамика между снимками</h2>
${table(['Показатель', m.prev_week, m.cur_week, 'Δ'], kpiRows)}
<p>Новых акций: <b>${m.kpi.new}</b> (${m.kpi.share_new_pct}% текущего снимка), завершилось: <b>${m.kpi.ended}</b>.</p>
${table(['Конкурент', 'Было', 'Стало', 'Новых', 'Завершились', 'Доля новых'], churnRows)}

<h2 style="font-size:18px">Структура акций</h2>
<img src="${chartUrl}" alt="Структура акций по типам" style="max-width:100%">

${mechRows.length ? `<h2 style="font-size:18px">Сдвиги механик</h2>${table(['Конкурент', 'Механика', m.prev_week, m.cur_week, 'Δ'], mechRows)}` : ''}

<h2 style="font-size:18px">Глубина скидок</h2>
${table(['Конкурент', 'Акций с %', 'Средняя, %', 'Медиана, %', 'Максимум, %'], depthRows)}
<p style="color:#666;font-size:13px">«До −60%» это потолок на категорию, а не фиксированная скидка; проценты бонусами не учитываются.</p>

${overlapRows.length ? `<h2 style="font-size:18px">Один бренд у нескольких конкурентов</h2>${table(['Бренд', ...m.competitors], overlapRows)}` : ''}

${ai.threats && ai.threats.length ? `<h2 style="font-size:18px">Угрозы</h2>${ul(ai.threats)}` : ''}
${ai.opportunities && ai.opportunities.length ? `<h2 style="font-size:18px">Возможности</h2>${ul(ai.opportunities)}` : ''}

<h2 style="font-size:18px">Качество данных</h2>
${qualityWarn ? '<p style="color:#b00"><b>Внимание:</b> доля неопределённых значений выше 40%, выводы по сегментам, категориям и срокам ненадёжны.</p>' : ''}
<p>Без сегмента: ${q.unknown_segment_pct}%, без категории: ${q.unknown_category_pct}%, без срока: ${q.unknown_duration_pct}%, бренд multiple/unknown: ${q.brand_multiple_or_unknown_pct}%, разметка с уверенностью high: ${q.high_confidence_pct}%. Снимков в базе: ${m.weeks_total}.</p>
<p style="color:#666;font-size:13px">${m.notes.map(esc).join('<br>')}</p>
</div>`;

return [{ json: { subject: `CI-отчёт: акции конкурентов, ${m.cur_week}`, html } }];

// Сравнение текущей версии страницы с прошлой. Источник текущей версии: Edit Fields1
const current = $('Edit Fields1').first().json;
const norm = t => String(t ?? '').replace(/\s+/g, ' ').trim();

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.page === current.page && norm(row.content));
rows.sort((a, b) => new Date(b.updatedAt ?? 0) - new Date(a.updatedAt ?? 0));
const previous = rows[0];

let comparison_status;
if (!norm(current.content)) comparison_status = 'empty';              // страницу не удалось прочитать
else if (!previous) comparison_status = 'first_check';
else if (norm(current.content) === norm(previous.content)) comparison_status = 'unchanged';
else comparison_status = 'changed';

return [{
  json: {
    page: current.page,
    company: current.company,
    checked_at: current.checked_at,
    content: current.content,
    previous_content: previous?.content ?? '',
    comparison_status,
    changed: comparison_status === 'changed'
  }
}];

// Сравнение текущей версии страницы с прошлой. Источник текущей версии: Edit Fields
const current = $('Edit Fields').first().json;
const norm = t => String(t ?? '').replace(/\s+/g, ' ').trim();

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.page === current.page && norm(row.content));
rows.sort((a, b) => new Date(b.updatedAt ?? 0) - new Date(a.updatedAt ?? 0));
const previous = rows[0];

let comparison_status;
if (!norm(current.content)) comparison_status = 'empty';              // страницу не удалось прочитать
else if (!previous) comparison_status = 'first_check';
else if (norm(current.content) === norm(previous.content)) comparison_status = 'unchanged';
else comparison_status = 'changed';

return [{
  json: {
    page: current.page,
    company: current.company,
    checked_at: current.checked_at,
    content: current.content,
    previous_content: previous?.content ?? '',
    comparison_status,
    changed: comparison_status === 'changed'
  }
}];

// Разбор ответа модели (шаг извлечения акций). Ошибка одной страницы не должна останавливать цикл.
// Достаёт первый полный JSON из ответа модели (убирает ```json, терпит запятую перед } и ])
function extractJson(raw) {
  if (raw !== null && typeof raw === 'object') return raw;
  if (typeof raw !== 'string') throw new Error('Поле output отсутствует или не является строкой');
  const text = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  const start = text.search(/[\[{]/);
